class Solution {
public:
    int maxCoins(vector<int>& nums) {
        // 添加虛擬邊界
        nums.insert(nums.begin(), 1);
        nums.push_back(1);
        int n = nums.size();

        vector<vector<int>> dp(n, vector<int>(n, 0));

        // 按區間長度遞增
        for (int len = 2; len < n; len++) {
            for (int i = 0; i < n - len; i++) {
                int j = i + len;
                // 嘗試最後戳破 k
                for (int k = i + 1; k < j; k++) {
                    int coins = nums[i] * nums[k] * nums[j];
                    dp[i][j] = max(dp[i][j], 
                                   dp[i][k] + dp[k][j] + coins);
                }
            }
        }

        return dp[0][n - 1];
    }
};

